'use strict';
const C=SportCo,KEY='vauban-sportco-v1',$=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let db=C.empty(),view='landing',selected=new Set(),activeTeam='',activeMatch='',dialogSubmit=null,noticeTimer,terrainMode=false;
try{const raw=localStorage.getItem(KEY);if(raw)db=C.validate(JSON.parse(raw))}catch(e){notify('La sauvegarde locale ne peut pas être lue. Elle reste conservée ; importe une sauvegarde valide.');}
const cls=()=>db.classes.find(c=>c.id===db.selectedClass),session=()=>db.sessions.find(s=>s.id===db.selectedSession&&s.classId===db.selectedClass),pupil=id=>cls()?.students.find(p=>p.id===id),team=id=>session()?.teams.find(t=>t.id===id),context=()=>activeMatch?session().matches.find(m=>m.id===activeMatch):session();
function notify(text){$('notice').textContent=text;$('notice').hidden=false;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('notice').hidden=true,5500)}
function save(){try{localStorage.setItem(KEY,JSON.stringify(db));$('saved').textContent='✓ Enregistré sur cet appareil · '+new Date().toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'});return true}catch(e){$('saved').textContent='Sauvegarde locale indisponible';notify('Sauvegarde impossible : exporte tes données avant de fermer.');return false}}
function run(fn){try{fn()}catch(e){notify(e.message)}}
function normalize(){if(!cls())db.selectedClass=db.classes[0]?.id||'';if(!session())db.selectedSession=db.sessions.filter(s=>s.classId===db.selectedClass).at(-1)?.id||'';if(session()&&!team(activeTeam))activeTeam=session().teams[0]?.id||'';if(activeMatch&&!session()?.matches.some(m=>m.id===activeMatch))activeMatch=''}
function button(action,label,attrs='',css=''){return `<button data-action="${action}" ${attrs} class="${css}">${label}</button>`}
function render(){if(view==='student'){document.body.classList.toggle('gateway-mode',false);document.body.classList.toggle('terrain-focus',true);$('content').innerHTML=studentHTML();return}document.body.classList.toggle('gateway-mode',['landing','student-gateway'].includes(view));if(['landing','student-gateway'].includes(view)){document.body.classList.toggle('terrain-focus',false);$('content').innerHTML=view==='landing'?landingHTML():studentGatewayHTML();return}normalize();document.body.classList.toggle('terrain-focus',view==='observe'||view==='student');$('classSelect').innerHTML=db.classes.length?db.classes.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join(''):'<option value="">Créer une classe</option>';$('classSelect').value=db.selectedClass;$('sessionSelect').innerHTML=db.sessions.filter(s=>s.classId===db.selectedClass).map(s=>`<option value="${s.id}">${esc(s.label)} · ${esc(s.date)}</option>`).join('')||'<option>Aucune séance</option>';$('sessionSelect').value=db.selectedSession;const current=session()?.sport||'';$('sportSelect').value=current==='Activité à choisir'?'':current;$('sportSelect').disabled=!session();$('sessionClock').hidden=!session();$('sessionClock').innerHTML=session()&&view!=='observe'&&view!=='student'?clockHTML(session()):'';$('nav').innerHTML=[['home','Accueil'],['teams','Équipes'],['criteria','Observations'],['observe','Sur le terrain'],['results','Bilan']].map(([key,label])=>button('view',label,`data-view="${key}" ${view===key?'aria-current="page"':''}`,view===key?'active':'')).join('');if(!cls()){$('content').innerHTML=`<section class="card empty"><span class="step">Votre carnet de terrain</span><h2>Une classe. Des équipes. Du jeu.</h2><p>Ajoute ta liste d’élèves, touche les noms pour constituer tes équipes, puis choisis ce que tu souhaites observer.</p>${button('class-dialog','＋ Ajouter ma première classe','','primary')} ${button('demo','Essayer avec des élèves fictifs','','secondary')}</section>`;return}if(!session()){C.newSession(db,cls().id);save()};$('content').innerHTML=({home:homeHTML,teams:teamsHTML,criteria:criteriaHTML,observe:observeHTML,results:resultsHTML,student:()=>studentHTML()}[view])()}
function landingHTML(){return `<section class="landing"><div class="landing-brand"><span class="eyebrow">VAUBAN · EPS</span><div class="landing-symbol" aria-hidden="true">● ● ●<br>● ● ●</div><h1>Sports collectifs</h1><p>Jouer. Observer. Progresser.</p></div><div class="mode-choices">${button('teacher-entry','<span class="mode-icon" aria-hidden="true">▦</span><strong>Mode professeur</strong><span>Préparer · Observer · Faire le bilan</span>','','mode-choice teacher-choice')}${button('student-gateway','<span class="mode-icon" aria-hidden="true">◎</span><strong>Mode élève</strong><span>Choisir · Observer · Échanger</span>','','mode-choice student-choice')}</div>${button('visual-guide','ⓘ Mode d’emploi','','guide-button')}<small class="landing-version">v1.20</small></section>`}
function studentGatewayHTML(){return studentHTML()}
function visualGuide(){const steps=(items)=>`<div class="guide-steps">${items.map(([title,body],i)=>`<div class="guide-step guide-tone-${i}"><span class="guide-number">${i+1}</span><div><strong>${title}</strong><p>${body}</p></div></div>`).join('')}</div>`;openDialog('Mode d’emploi',`<div class="guide-columns"><section><h3 class="guide-prof">Mode professeur</h3>${steps([['Préparer','Choisis la classe, l’activité et les équipes.'],['Observer','Choisis tes critères. Sur le terrain, touche les boutons.'],['Saisir les scores','Scores / Rotations : terrains au premier accès, puis − / +.'],['Partager le bilan','Bilan → nom de l’élève. Exporte le fichier HTML.']])}<div class="guide-tip"><strong>Pour confier l’appareil aux élèves</strong><p>Donne les observables à compter. Les élèves les saisissent dans leur espace, avec les noms des joueurs.</p></div></section><section><h3 class="guide-pupil">Mode élève</h3>${steps([['Mon groupe','Écris l’équipe et le nom / prénom des joueurs.'],['Mes observables','Saisis ceux du professeur : individuels et collectifs.'],['J’observe','Compteur : + / −. Appréciation : touche un niveau.'],['J’échange','Terminer → montre le bilan aux joueurs.']])}<div class="guide-tip"><strong>Tu peux reprendre plus tard</strong><p>Retrouve tes matchs dans « Mes matchs sur cet appareil ».</p></div></section></div><p class="guide-local">Les séances et résultats restent sur l’appareil utilisé.</p>`,null);$('dialog').classList.toggle('guide-dialog',true)}
function homeHTML(){const s=session(),present=cls().students.filter(p=>!s.absent.includes(p.id)).length;return `<div class="metrics"><div class="metric"><span class="count">${present}<small style="font-size:14px"> / ${cls().students.length}</small></span>élèves présents</div><div class="metric"><span class="count">${s.teams.length}</span>équipes</div><div class="metric"><span class="count">${s.matches.length}</span>matchs enregistrés</div></div><section class="card"><div class="row"><div><span class="step">Préparer la séance</span><h2>${esc(s.label)} · ${esc(s.sport)}</h2><p class="muted">${esc(cls().name)} · ${esc(s.date)} · Un iPad pour observer toute la classe</p></div><div>${button('settings','Date et activité')} ${button('presence','Présents / absents')} ${button('delete-class','Supprimer cette classe','','danger')}</div></div><div class="team-grid" style="margin-top:20px"><div class="team-card" style="--team:#245de9"><span class="step">01 · Répartir</span><h3>Créer les équipes</h3><p class="muted">Touche 3 à 6 élèves, choisis une couleur et crée l’équipe.</p>${button('view','Composer les équipes','data-view="teams"','secondary')}</div><div class="team-card" style="--team:#9b7c24"><span class="step">02 · Choisir</span><h3>Qu’observer aujourd’hui ?</h3><p class="muted">${s.criteria.filter(k=>k.scope==='individual').length} critères individuels · ${s.criteria.filter(k=>k.scope==='team').length} collectifs</p>${button('view','Choisir mes critères','data-view="criteria"')}</div><div class="team-card" style="--team:#168663"><span class="step">03 · Jouer</span><h3>Sur le terrain</h3><p class="muted">Une page par équipe, des boutons rapides et les scores.</p>${button('view','Commencer les observations','data-view="observe"','primary')}</div></div></section><section class="card"><div class="row"><h3>Observation élèves</h3><div>${button('peer-entry','Ouvrir l’espace élèves','','primary')}</div></div><p class="muted">Les élèves saisissent leur groupe et tes observables. Un bilan à montrer en fin de match.</p></section><section class="card"><h3>Mes équipes</h3>${s.teams.length?teamCards():`<p class="muted">Tes équipes apparaîtront ici dès leur création.</p>`}</section>`}
function teamCards(){return `<div class="team-grid">${session().teams.map(t=>`<div class="team-card" style="--team:${t.color}"><div class="row"><h3>${esc(t.name)}</h3><span class="pill">${t.members.length} élèves</span></div><p class="members">${t.members.map(id=>esc(pupil(id)?.name)).join(' · ')}</p><div class="row">${button('open-team','Observer',`data-id="${t.id}"`,'primary')}${button('rename-team','Renommer',`data-id="${t.id}"`)} ${button('edit-team','Modifier',`data-id="${t.id}"`)}</div></div>`).join('')}</div>`}
function teamsHTML(){const s=session(),assigned=new Map(s.teams.flatMap(t=>t.members.map(id=>[id,t])));return `<section class="card"><div class="row"><div><span class="step">Composer les équipes</span><h2>Touche les élèves à regrouper</h2><p class="muted">3, 4, 5 ou 6 élèves par équipe. Une couleur pour retrouver chacun rapidement.</p></div><div>${button('repair-roster','Nettoyer les noms de cette classe')} ${button('transfer','Déplacer un élève')} ${button('presence','Présents / absents')}</div></div><div class="selectbar"><strong>${selected.size} élève${selected.size>1?'s':''} sélectionné${selected.size>1?'s':''}</strong><div>${button('clear-selection','Effacer la sélection')}${button('create-team','＋ Créer cette équipe',selected.size<3||selected.size>6?'disabled':'','primary')}</div></div><label>Rechercher un élève<input id="searchPupil" type="search" placeholder="Chercher un nom…"></label><div class="grid" style="margin-top:16px">${cls().students.map(p=>{const t=assigned.get(p.id),abs=s.absent.includes(p.id);return `<button class="pupil ${selected.has(p.id)?'selected':''} ${t?'assigned':''} ${abs?'absent':''}" data-action="select-pupil" data-id="${p.id}" data-search="${esc(p.name.toLocaleLowerCase('fr'))}" style="--team:${t?.color||'#89b39d'}" ${t||abs?'disabled':''} aria-pressed="${selected.has(p.id)}"><strong>${esc(p.name)}</strong><small>${abs?'Absent':t?esc(t.name):selected.has(p.id)?'✓ Sélectionné':'Disponible'}</small></button>`}).join('')}</div></section><section class="card"><h2>${s.teams.length} équipe${s.teams.length>1?'s':''}</h2>${teamCards()}</section>`}
const typeLabel={level:'4 niveaux',binary:'Réussi / non réussi',counter:'Compteur + / −'};
function criteriaHTML(){const s=session();return `<section class="card"><div class="row"><div><span class="step">Votre regard, vos critères</span><h2>Qu’observer aujourd’hui ?</h2><p class="muted">Commence avec 2 critères individuels et 1 collectif. Tu peux en ajouter et préciser les élèves concernés.</p></div><div>${button('criterion-dialog','＋ Ajouter un critère','','primary')} ${button('match-dialog','Créer un match / Saisir le score','','secondary')}</div></div><p class="muted">Le résultat est enregistré pour les deux équipes. Crée le match, puis saisis les deux scores sur la page du terrain.</p><div class="criteria-list" style="margin-top:20px">${['individual','team'].map(scope=>`<div><h3>${scope==='individual'?'Pour chaque élève':'Pour l’équipe'}</h3>${s.criteria.filter(k=>k.scope===scope).map(k=>`<div class="criterion-card"><div class="row"><strong>${esc(k.label)}</strong>${button('edit-criterion','Modifier',`data-id="${k.id}"`)}</div><p>${typeLabel[k.type]} · ${scope==='team'?'Évaluation collective':k.targets===null?'Tous les élèves':k.targets.map(id=>esc(pupil(id)?.name)).join(', ')}</p></div>`).join('')||'<p class="muted">Aucun critère pour le moment.</p>'}</div>`).join('')}</div></section>`}
function observerControl(subject,k){const val=context()?.observations?.[subject]?.[k.id];const attrs=`data-subject="${subject}" data-criterion="${k.id}"`;return `<div class="criterion"><div class="row"><div class="criterion-title">${esc(k.label)}</div>${val!==undefined?button('clear-observation','Effacer',attrs,'reset'):'<span class="muted" style="font-size:12px">Non observé</span>'}</div>${k.type==='level'?`<div class="levels">${['Non acquis','En cours','Acquis','Très bien'].map((label,n)=>button('observation',`<strong>${['×','~','✓','★'][n]}</strong>${label}`,attrs+` data-value="${n}" aria-pressed="${val===n}"`,`l${n} ${val===n?'chosen':''}`)).join('')}</div>`:k.type==='binary'?`<div class="binary">${[[0,'× Non réussi'],[1,'✓ Réussi']].map(([n,label])=>button('observation',label,attrs+` data-value="${n}" aria-pressed="${val===n}"`,val===n?'chosen':'')).join('')}</div>`:`<div class="counter">${button('counter','−',attrs+' data-delta="-1" aria-label="Retirer une observation" '+(val===undefined||val===0?'disabled':''))}<output aria-label="Nombre observé">${val===undefined?'—':val}</output>${button('counter','＋',attrs+' data-delta="1" aria-label="Ajouter une observation"')}</div>`}</div>`}
function notesHTML(subject,label){return `<label style="margin-top:12px">${label}<textarea class="notes" data-note="${subject}" placeholder="Une remarque utile…" maxlength="1000">${esc(context()?.notes?.[subject]||'')}</textarea></label>`}
function compactClock(m){const ms=C.clockRemaining(m),running=m.clock?.running;return `<div class="compact-clock"><div class="clock-face"><small>${m.classId?'Chrono libre':'Chrono match'}</small><output class="clock-time ${ms===0?'expired':''}" data-clock="${m.id}" role="timer" aria-label="Temps restant">${clockText(ms)}</output></div>${button(running?'clock-pause':'clock-start',running?'Ⅱ':'▶',`data-id="${m.id}" aria-label="${running?'Pause':'Démarrer le chrono'}" ${ms===0?'disabled':''}`,'clock-play')}</div>`}
function fastScore(m,t){const v=m?(m.a===t.id?m.scoreA:m.scoreB):null;return `<div class="fast-score" style="--team:${t.color}"><strong>${esc(t.name)}</strong><div>${button('quick-score','−',`data-match="${m?.id||''}" data-team="${t.id}" data-delta="-1" aria-label="Retirer un point à ${esc(t.name)}" ${!m||v===null||v===0?'disabled':''}`)}<output>${v??'—'}</output>${button('quick-score','+',`data-match="${m?.id||''}" data-team="${t.id}" data-delta="1" aria-label="Ajouter un point à ${esc(t.name)}" ${!m?'disabled':''}`,'score-plus')}</div></div>`}
function observeHTML(){const s=session();if(!s.teams.length)return `<section class="card empty"><h2>Crée tes équipes pour commencer</h2>${button('view','Créer les équipes','data-view="teams"','primary')} ${button('terrain-back','Retour')}</section>`;const t=team(activeTeam),matches=s.matches.filter(m=>[m.a,m.b].includes(t.id));if(activeMatch&&!matches.some(m=>m.id===activeMatch))activeMatch='';const m=s.matches.find(m=>m.id===activeMatch),opponent=m?team(m.a===t.id?m.b:m.a):null;
return `<section class="field-top"><div class="field-heading">${button('terrain-back','← Retour','','field-back')}<div class="field-team-tabs" aria-label="Choisir l’équipe">${s.teams.map(x=>button('switch-team',esc(x.name),`data-id="${x.id}" style="--team:${x.color}" aria-pressed="${x.id===t.id}"`,x.id===t.id?'active':'')).join('')}</div>${compactClock(s)}</div><div class="pool-strip">${button('pool','Scores / Rotations','','primary')}${m?button('pool',`Match ${s.matches.indexOf(m)+1} · ${esc(team(m.a)?.name)} ${m.scoreA??'—'} – ${m.scoreB??'—'} ${esc(team(m.b)?.name)}`,'','match-recap'):'<span class="muted">Choisis une rencontre dans la poule.</span>'}${m?button('pool-next','Rotation suivante','', 'small-action'):''}</div><div class="field-tools">${button('field-settings','Réglages de la séance')}${button('terrain-mode',terrainMode?'Quitter le plein écran':'Plein écran')}</div></section><p class="observation-context">${esc(t.name)} · ${m?'Match '+(s.matches.indexOf(m)+1)+' contre '+esc(opponent.name):'Observation générale de la séance'}</p><div class="field-layout"><section class="individual-area"><h2 class="area-title">Observations des élèves</h2><div class="field-cards" style="--pupil-columns:${t.members.length>4?3:Math.max(1,t.members.length)}">${t.members.map(id=>{const p=pupil(id),abs=s.absent.includes(id),criteria=s.criteria.filter(k=>k.scope==='individual'&&(k.targets===null||k.targets.includes(id)));return `<section class="observer card" style="--team:${t.color}"><h3>${esc(p?.name)}</h3>${abs?'<p class="muted">Absent</p>':criteria.map(k=>observerControl(id,k)).join('')||'<p class="muted">Aucun critère pour cet élève.</p>'}${!abs?'<details class="field-note"><summary>Remarque</summary>'+notesHTML(id,'Remarque individuelle')+'</details>':''}</section>`}).join('')}</div></section><aside class="collective-area"><h2 class="area-title">Observation de l’équipe</h2><section class="observer card collective-card" style="--team:${t.color}"><h3>Équipe · ${esc(t.name)}</h3><span class="collective-label">Observation collective</span><div class="collective-criteria" style="--criteria-count:${Math.max(1,s.criteria.filter(k=>k.scope==='team').length)}">${s.criteria.filter(k=>k.scope==='team').map(k=>observerControl(t.id,k)).join('')||'<p class="muted">Aucun critère collectif.</p>'}</div><details class="field-note"><summary>Remarque</summary>${notesHTML(t.id,'Remarque collective')}</details></section></aside></div>`}

function poolRanking(){return `<h3>Classement</h3><p class="muted">Victoire 3 pts · Nul 1 · Défaite 0. Départage : différence, puis points marqués. Scores incomplets exclus.</p><div class="tablewrap"><table><thead><tr><th>Rang</th><th>Équipe</th><th>J</th><th>V</th><th>N</th><th>D</th><th>Diff.</th><th>Pts</th></tr></thead><tbody>${C.standings(session()).map((r,i)=>`<tr><td>${i+1}</td><td>${esc(r.team.name)}</td><td>${r.played}</td><td>${r.w}</td><td>${r.d}</td><td>${r.l}</td><td>${r.for-r.against}</td><td><strong>${r.points}</strong></td></tr>`).join('')}</tbody></table></div>`}
function poolScoreControl(m,side){const id=side==='a'?m.a:m.b,v=side==='a'?m.scoreA:m.scoreB;return `<div class="pool-score-team"><strong>${esc(team(id)?.name)}</strong><div class="pool-stepper">${button('pool-score','−',`type="button" data-match="${m.id}" data-team="${id}" data-delta="-1" aria-label="Retirer un point à ${esc(team(id)?.name)}" ${v===null||v===0?'disabled':''}`)}<input type="number" inputmode="numeric" min="0" max="9999" step="1" data-score="${side}" data-match="${m.id}" value="${v??''}" placeholder="—" aria-label="Score ${esc(team(id)?.name)}">${button('pool-score','+',`type="button" data-match="${m.id}" data-team="${id}" data-delta="1" aria-label="Ajouter un point à ${esc(team(id)?.name)}"`)}</div></div>`}
function fieldSettings(){const s=session(),t=team(activeTeam),matches=s.matches.filter(m=>[m.a,m.b].includes(t.id)),running=s.clock?.running,m=s;openDialog('Réglages de la séance',`<div class="settings-grid">${button('rename-team','Renommer '+esc(t.name),`type="button" data-id="${t.id}"`)}${button('presence','Présents / absents','type="button"')}${button('field-criteria','Modifier les critères','type="button"')}${button('pool-settings','Modifier l’organisation','type="button"')}</div><h3>Chrono</h3><div class="clock-options"><label>Minutes<input type="number" min="1" max="120" step="1" data-duration="${m.id}" value="${Math.round((m.clock?.durationMs||300000)/60000)}" ${running?'disabled':''}></label>${button('clock-reset','↺',`data-id="${m.id}" aria-label="Réinitialiser le chrono" title="Réinitialiser le chrono"`)}</div><h3>Contexte des observations</h3><label>Observations pour<select id="contextSelect"><option value="">Séance générale</option>${matches.map(x=>`<option value="${x.id}" ${x.id===activeMatch?'selected':''}>Match ${s.matches.indexOf(x)+1} · ${esc(team(x.a===t.id?x.b:x.a)?.name)} · ${x.scoreA??'—'}–${x.scoreB??'—'}</option>`).join('')}</select></label>`,null)}
function poolSetup(){const s=session();if(s.teams.length<2){notify('Crée au moins deux équipes pour préparer la poule.');return}openDialog('Combien de terrains ?',`<p>Choisis le nombre de terrains disponibles pour organiser les matchs, l’arbitrage et le repos.</p><div class="court-picker">${button('court-step','−','type="button" data-delta="-1" aria-label="Un terrain de moins"')}<label>Terrains<input id="courtCount" type="number" inputmode="numeric" min="1" max="100" step="1" value="${s.courts||1}"></label>${button('court-step','+','type="button" data-delta="1" aria-label="Un terrain de plus"')}</div><p class="muted">Les scores et observations existants sont conservés.</p>`,()=>{const count=Number($('courtCount').value);if(!Number.isInteger(count)||count<1||count>100)throw Error('Choisis entre 1 et 100 terrains.');s.courts=count;save();poolDialog()},'Valider et voir les rotations')}
function poolDialog(){const s=session();if(s.teams.length<2){notify('Crée au moins deux équipes pour préparer la poule.');return}const rounds=C.poolRotations(s);save();openDialog('Scores / Rotations',`<div class="row"><strong>${s.courts||1} terrain(s) disponible(s)</strong>${button('pool-settings','Modifier l’organisation','type="button"')}</div><p>Les matchs d’une rotation se jouent en même temps. Saisis les scores avec − / + ou au clavier.</p><div class="pool-list">${rounds.map((r,i)=>`<section class="rotation-frame rotation-color-${i%4} ${r.matches.some(m=>m.id===activeMatch)?'active-rotation':''}"><div class="row"><h3>Rotation ${i+1}</h3>${r.matches.some(m=>m.id===activeMatch)?'<span class="pill">En cours d’observation</span>':''}</div><p class="rotation-referees">Arbitrage : ${r.referees.length?r.referees.map(id=>esc(team(id)?.name)).join(' · '):'à prévoir'} · Au repos : ${r.rest.length?r.rest.map(id=>esc(team(id)?.name)).join(' · '):'aucune équipe'}</p>${r.matches.map((m,j)=>`<section class="pool-row ${m.id===activeMatch?'current-match':''}"><div class="pool-number"><small>Terrain</small>${j+1}</div>${poolScoreControl(m,'a')}<span>–</span>${poolScoreControl(m,'b')}<div class="pool-match-actions">${button('pool-observe','Observer',`type="button" data-id="${m.id}"`)}${button('clear-match-score','Effacer le score',`type="button" data-id="${m.id}"`,'reset')}</div><div class="match-referee">Arbitrage : ${r.assignments[j].referee?esc(team(r.assignments[j].referee)?.name):'à prévoir sur ce terrain'}</div></section>`).join('')}</section>`).join('')}</div><div id="poolRanking">${poolRanking()}</div>`,null);$('dialog').classList.toggle('pool-dialog',true);document.querySelector('.active-rotation')?.scrollIntoView?.({block:'start'})}
function updatePoolScores(){const s=session();document.querySelectorAll('.pool-stepper input').forEach(el=>{const m=s.matches.find(m=>m.id===el.dataset.match);el.value=m[el.dataset.score==='a'?'scoreA':'scoreB']??''});document.querySelectorAll('[data-action="pool-score"]').forEach(el=>{const m=s.matches.find(m=>m.id===el.dataset.match),v=m[m.a===el.dataset.team?'scoreA':'scoreB'];el.disabled=el.dataset.delta==='-1'&&(v===null||v===0)});$('poolRanking').innerHTML=poolRanking()}
function observePoolMatch(id){const m=session().matches.find(m=>m.id===id);if(!m)return;activeMatch=m.id;activeTeam=m.a;session().poolMatch=m.id;view='observe';save();$('dialog').close();render()}
function nextPoolMatch(){if(!session().courts){poolSetup();return}const rounds=C.poolRotations(session()),i=rounds.findIndex(r=>r.matches.some(m=>m.id===activeMatch)),next=rounds[i+1];if(!next){notify('Dernière rotation. Consulte le classement.');poolDialog();return}observePoolMatch(next.matches[0].id);poolDialog()}
function timerFor(id){const s=session();return s?.id===id?s:s?.matches.find(m=>m.id===id)}
function clockText(ms){const n=Math.ceil(ms/1000);return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0')}
function clockHTML(m){const t=m.clock,ms=C.clockRemaining(m);return `<div class="match-clock"><div><strong>${m.classId?'Chrono libre · séance':'Temps du match'}</strong><output class="clock-time ${ms===0?'expired':''}" data-clock="${m.id}" role="timer" aria-label="Temps restant">${clockText(ms)}</output><span data-clock-status="${m.id}" class="muted">${ms===0?'Temps écoulé':t?.running?'En cours':'En pause / prêt'}</span></div><label>Durée (minutes)<input type="number" min="1" max="120" step="1" data-duration="${m.id}" value="${Math.round((t?.durationMs||300000)/60000)}" ${t?.running?'disabled':''}></label><div>${button(t?.running?'clock-pause':'clock-start',t?.running?'Pause':ms===0?'Terminé':t&&ms<t.durationMs?'Reprendre':'Démarrer',`data-id="${m.id}" ${ms===0?'disabled':''}`,'primary')} ${button('clock-reset','Remettre à zéro',`data-id="${m.id}"`)}</div></div>`}
function scoreHTML(m){return `<div class="scorebox"><strong>${esc(team(m.a)?.name)}</strong><input type="number" min="0" max="9999" step="1" data-score="a" data-match="${m.id}" value="${m.scoreA??''}" placeholder="—" aria-label="Score ${esc(team(m.a)?.name)}"><strong>—</strong><input type="number" min="0" max="9999" step="1" data-score="b" data-match="${m.id}" value="${m.scoreB??''}" placeholder="—" aria-label="Score ${esc(team(m.b)?.name)}"><strong>${esc(team(m.b)?.name)}</strong><span class="pill">${m.scoreA===null||m.scoreB===null?'Score à compléter':'Score enregistré'}</span></div>${clockHTML(m)}`}
function valueLabel(k,v){return k.type==='level'?['Non acquis','En cours','Acquis','Très bien'][v]:k.type==='binary'?v?'Réussi':'Non réussi':String(v)}
function pupilSummary(p,s){const relevant=s.criteria.filter(k=>k.scope==='individual'&&(k.targets===null||k.targets.includes(p.id)));return relevant.map(k=>{const entries=[{observations:s.observations,label:'Général'},...s.matches.map((m,i)=>({...m,label:'M'+(i+1)}))].filter(x=>x.observations?.[p.id]?.[k.id]!==undefined);return `<div><strong>${esc(k.label)}</strong> : ${entries.length?entries.map(x=>esc(x.label)+' '+esc(valueLabel(k,x.observations[p.id][k.id]))).join(' · '):'<span class="muted">Non observé</span>'}</div>`}).join('')||'<span class="muted">Aucun critère</span>'}
function reportCriteria(subject,criteria,s){return criteria.map(k=>{const values=C.valuesFor(s,subject,k.id);let result='Non observé';if(values.length){if(k.type==='counter')result=`${values.reduce((a,b)=>a+b,0)} au total · ${values.length} relevé(s)`;else result=[...new Set(values)].sort((a,b)=>a-b).map(v=>`${esc(valueLabel(k,v))} : ${values.filter(x=>x===v).length}`).join(' · ')}return `<div class="report-criterion"><strong>${esc(k.label)}</strong><p>${result}</p></div>`}).join('')||'<p class="muted">Aucun critère défini.</p>'}
function pupilReport(p,s){const t=s.teams.find(t=>t.members.includes(p.id)),rows=C.standings(s),r=rows.find(r=>r.team.id===t?.id),individual=s.criteria.filter(k=>k.scope==='individual'&&(k.targets===null||k.targets.includes(p.id))),collective=s.criteria.filter(k=>k.scope==='team');const notes=subject=>[...new Set([s,...s.matches].map(x=>x.notes?.[subject]).filter(Boolean))].map(n=>`<p class="report-note">${esc(n)}</p>`).join('');return `<h2>${esc(p.name)}</h2><p class="muted">${esc(t?.name||'Sans équipe')}${s.absent.includes(p.id)?' · Absent(e) à cette séance':''}</p><section class="report-section"><h3>Mon bilan individuel</h3>${reportCriteria(p.id,individual,s)}${notes(p.id)}</section><section class="report-section"><h3>Le bilan collectif de mon équipe</h3>${t?reportCriteria(t.id,collective,s)+notes(t.id):'<p>Aucune équipe attribuée.</p>'}</section><section class="report-section"><h3>Résultats de mon équipe</h3>${r?`<div class="report-metrics"><div><strong>${r.played?rows.indexOf(r)+1:'—'}</strong><span>Classement${r.played?' / '+rows.length:''}</span></div><div><strong>${r.w}</strong><span>Gagnés</span></div><div><strong>${r.l}</strong><span>Perdus</span></div>${r.d?`<div><strong>${r.d}</strong><span>Nuls</span></div>`:''}</div>${!r.played?'<p class="muted">Aucun match joué avec un score complet.</p>':''}`:'<p>Aucune équipe attribuée.</p>'}</section>`}
function resultsHTML(){const s=session();return `<section class="card"><div class="row"><div><h2>Bilan des élèves</h2><p class="muted">${esc(cls().name)} · ${esc(s.label)} · ${esc(s.sport)}</p></div>${button('export-report','Télécharger le bilan HTML','','primary')}</div><p>Touche un nom pour consulter le bilan individuel, le collectif et les résultats de son équipe.</p><div class="report-roster">${cls().students.map(p=>button('pupil-report',esc(p.name),`data-id="${p.id}"`)).join('')}</div></section>`}
function openDialog(title,body,submit,submitLabel='Enregistrer'){$('dialog').classList.toggle('guide-dialog',false);$('dialog').classList.toggle('pool-dialog',false);dialogSubmit=submit;$('dialogTitle').textContent=title;$('dialogBody').innerHTML=body;$('dialogActions').innerHTML=button('close-dialog','Fermer','type="button"')+(submit?`<button type="submit" class="primary">${submitLabel}</button>`:'');$('dialog').showModal()}
function deleteClassDialog(){const c=cls();if(!c)return;const n=db.sessions.filter(s=>s.classId===c.id).length;openDialog('Supprimer la classe '+c.name,`<p>Supprimer <strong>${esc(c.name)}</strong>, ses <strong>${c.students.length} élèves</strong> et ses <strong>${n} séance(s)</strong> avec équipes, observations et matchs ?</p><p>Les autres classes restent conservées. Cette suppression est définitive sur cet appareil.</p>${button('export','Exporter une sauvegarde avant de supprimer','type="button"')}`,()=>{C.removeClass(db,c.id);selected.clear();activeTeam='';activeMatch='';view='home';save();$('dialog').close();render();notify('Classe supprimée. Les autres classes sont conservées.')},'Oui, supprimer cette classe');$('dialogActions').querySelector('button[type="submit"]').className='danger'}
function repairRosterDialog(){const c=cls();if(!c)return;const plan=C.rosterRepairPlan(c);if(!plan.length){notify('Les noms de cette classe sont déjà propres.');return}openDialog('Nettoyer les noms de '+c.name,`<p>Corriger les noms importés depuis Pronote, en conservant les élèves et leurs observations.</p><ul>${plan.map(p=>`<li>${p.name?esc(p.name):'Retirer la carte des titres de colonnes'}</li>`).join('')}</ul><p class="muted">Les cartes de titres de colonnes seront retirées. Les équipes, matchs et observations des vrais élèves restent conservés.</p>`,()=>{const result=C.repairClassRoster(db,c.id);selected.clear();save();$('dialog').close();render();notify(result.renamed+' nom(s) corrigé(s), '+result.removed+' carte(s) de titres retirée(s).')},'Appliquer le nettoyage')}
function classDialog(){openDialog('Classes et élèves',`<div class="form-grid"><label class="wide">Classe<select id="classTarget"><option value="new">Créer une nouvelle classe</option>${db.classes.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label><label class="wide">Nom de la nouvelle classe<input id="className" placeholder="Ex. 4B" maxlength="100"></label><div class="wide row">${button('roster-file','Importer une liste TXT / CSV','type="button"')}${button('clean-roster','Nettoyer le collage Pronote','type="button"')}</div><input id="rosterFile" type="file" accept=".txt,.csv,.tsv,text/plain,text/csv" hidden><label class="wide">Liste à vérifier · nom et prénom, un élève par ligne<textarea id="studentNames" placeholder="NOM Prénom&#10;NOM Prénom"></textarea></label></div><p class="muted">CSV Pronote : seule la colonne Élèves est importée ; les titres et autres colonnes sont ignorés. Pour un collage simple, les informations à partir de la première date sont retirées. Vérifie les noms avant d’enregistrer. Le fichier doit présenter un élève par ligne, avec les noms en premier.</p><p class="muted">Pour une classe existante, les nouveaux noms sont ajoutés sans supprimer son historique.</p>${cls()?button('delete-class','Supprimer la classe actuelle : '+esc(cls().name),'type="button"','danger'):''}`,()=>{const target=$('classTarget').value,raw=$('studentNames').value,text=C.cleanRoster(raw);if(!text)throw Error('Ajoute au moins un nom et prénom.');if(text!==raw.trim()){$('studentNames').value=text;notify('Liste nettoyée. Vérifie les noms, puis appuie à nouveau sur Enregistrer.');return}if(target==='new')C.addClass(db,$('className').value,text);else{const c=db.classes.find(c=>c.id===target);C.appendStudents(c,text);db.selectedClass=c.id;db.selectedSession=db.sessions.filter(s=>s.classId===c.id).at(-1)?.id||''}selected.clear();activeTeam='';activeMatch='';save();$('dialog').close();render()});$('rosterFile').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>2*1024*1024)throw Error('Choisis une liste de moins de 2 Mo.');$('studentNames').value=C.cleanRoster(await file.text());notify('Liste chargée. Vérifie les noms avant d’enregistrer.')}catch(e){notify(e.message)}}}

function settingsDialog(){const s=session();openDialog('Date et activité',`<div class="form-grid"><label>Nom de la séance<input id="sessionName" value="${esc(s.label)}" maxlength="100"></label><label>Date<input id="sessionDate" type="date" value="${esc(s.date)}"></label><label class="wide">Activité<input id="sessionSport" list="sports" value="${esc(s.sport)}" maxlength="100"><datalist id="sports"><option>Basketball</option><option>Handball</option><option>Football</option><option>Volleyball</option><option>Rugby</option><option>Ultimate</option></datalist></label></div>`,()=>{const label=$('sessionName').value.trim(),sport=$('sessionSport').value.trim();if(!label||!sport||!$('sessionDate').value)throw Error('Renseigne le nom, la date et l’activité.');Object.assign(s,{label,sport,date:$('sessionDate').value});save();$('dialog').close();render()})}
function presenceDialog(){const s=session();openDialog('Présents / absents',`<p>Coche les élèves présents. Les absents restent dans leur équipe et leurs observations sont conservées.</p><div class="checks">${cls().students.map(p=>`<label class="check"><input type="checkbox" name="present" value="${p.id}" ${s.absent.includes(p.id)?'':'checked'}>${esc(p.name)}</label>`).join('')}</div>`,()=>{const present=new Set([...document.querySelectorAll('input[name="present"]:checked')].map(x=>x.value));s.absent=cls().students.filter(p=>!present.has(p.id)).map(p=>p.id);for(const id of s.absent)selected.delete(id);save();$('dialog').close();render()})}
function teamDialog(id){const s=session(),t=id?team(id):null;const members=t?t.members:[...selected];openDialog(t?'Modifier '+t.name:'Créer une équipe',`<div class="form-grid"><label>Nom<input id="teamName" value="${esc(t?.name||'Équipe '+(s.teams.length+1))}" maxlength="100"></label><label>Couleur<select id="teamColor">${C.colors.map((color,i)=>`<option value="${color}" ${color===(t?.color||C.colors[s.teams.length%C.colors.length])?'selected':''}>${['Bleu','Orange','Vert','Violet','Rose','Turquoise','Jaune','Gris'][i]}</option>`).join('')}</select></label></div><p class="muted">Sélectionne 3 à 6 élèves. Pour déplacer un élève, retire-le d’abord de son équipe.</p><div class="checks">${cls().students.map(p=>{const elsewhere=s.teams.some(x=>x.id!==t?.id&&x.members.includes(p.id));return `<label class="check"><input type="checkbox" name="teamMember" value="${p.id}" ${members.includes(p.id)?'checked':''} ${elsewhere?'disabled':''}>${esc(p.name)}${elsewhere?' · déjà affecté':''}</label>`}).join('')}</div>`,()=>{const ids=[...document.querySelectorAll('input[name="teamMember"]:checked')].map(x=>x.value);const result=C.putTeam(s,cls(),ids,$('teamName').value,$('teamColor').value,t?.id);activeTeam=result.id;selected.clear();save();$('dialog').close();render()})}
function renameTeamDialog(id){const t=team(id);if(!t)throw Error('Choisis une équipe.');openDialog('Renommer l’équipe',`<label>Nom de l’équipe<input id="renameTeamName" value="${esc(t.name)}" placeholder="Ex. Rouge, Vert, Bleu…" maxlength="100" required></label><p class="muted">Les élèves, matchs, scores et observations restent associés à cette équipe.</p>`,()=>{const name=$('renameTeamName').value.trim();if(!name)throw Error('Écris un nom pour cette équipe.');t.name=name;save();$('dialog').close();render()});$('renameTeamName').focus();$('renameTeamName').select()}
function terrainToggle(){terrainMode=!terrainMode;view='observe';render();if(terrainMode){document.documentElement.requestFullscreen?.().catch(()=>{})}else if(document.fullscreenElement){document.exitFullscreen?.().catch(()=>{})}}
function transferDialog(){const s=session();if(!s.teams.length){notify('Crée d’abord une équipe.');return}openDialog('Déplacer un élève',`<div class="form-grid"><label>Élève<select id="transferPupil">${cls().students.map(p=>`<option value="${p.id}">${esc(p.name)} · ${esc(s.teams.find(t=>t.members.includes(p.id))?.name||'Sans équipe')}</option>`).join('')}</select></label><label>Nouvelle équipe<select id="transferTeam"><option value="">Sans équipe</option>${s.teams.map(t=>`<option value="${t.id}">${esc(t.name)} · ${t.members.length} élèves</option>`).join('')}</select></label></div><p class="muted">Les observations déjà saisies restent liées à l’élève. Après un déplacement, une équipe peut compter moins de trois élèves. L’historique des autres séances reste conservé.</p>`,()=>{C.moveStudent(s,cls(),$('transferPupil').value,$('transferTeam').value);selected.clear();save();$('dialog').close();render()})}
function criterionDialog(id){const s=session(),k=id?s.criteria.find(k=>k.id===id):null;const used=k&&[s,...s.matches].some(x=>Object.values(x.observations).some(o=>o[k.id]!==undefined));openDialog(k?'Modifier le critère':'Ajouter une observation',`<div class="form-grid"><label class="wide">Ce que j’observe<input id="criterionName" value="${esc(k?.label||'')}" placeholder="Ex. Revenir défendre" maxlength="100"></label><label>Observation<select id="criterionScope" ${used?'disabled':''}><option value="individual" ${k?.scope==='team'?'':'selected'}>Individuelle</option><option value="team" ${k?.scope==='team'?'selected':''}>Collective</option></select></label><label>Saisie<select id="criterionType" ${used?'disabled':''}>${Object.entries(typeLabel).map(([v,l])=>`<option value="${v}" ${k?.type===v?'selected':''}>${l}</option>`).join('')}</select></label></div>${used?'<p class="muted">Des observations existent : le format est conservé.</p>':''}<div id="targetArea"><label class="check" style="margin-top:15px"><input type="checkbox" id="allTargets" ${!k||k.targets===null?'checked':''}>Appliquer à tous les élèves</label><div class="checks" id="targetChecks">${cls().students.map(p=>`<label class="check"><input type="checkbox" name="criterionTarget" value="${p.id}" ${k?.targets?.includes(p.id)?'checked':''}>${esc(p.name)}</label>`).join('')}</div></div>`,()=>{const targets=$('allTargets').checked?null:[...document.querySelectorAll('input[name="criterionTarget"]:checked')].map(x=>x.value);if(k){const label=$('criterionName').value.trim(),scope=$('criterionScope').value,type=$('criterionType').value;if(!label)throw Error('Renseigne le critère.');if(scope==='individual'&&targets!==null&&!targets.length)throw Error('Sélectionne au moins un élève.');Object.assign(k,{label,scope,type,targets:scope==='team'?null:targets})}else C.addCriterion(s,$('criterionName').value,$('criterionScope').value,$('criterionType').value,targets);save();$('dialog').close();render()});const update=()=>{$('targetArea').hidden=$('criterionScope').value==='team';$('targetChecks').hidden=$('allTargets').checked};$('criterionScope').onchange=update;$('allTargets').onchange=update;update()}
function matchDialog(id){const s=session();if(s.teams.length<2){notify('Crée au moins deux équipes pour enregistrer un match.');return}openDialog('Nouveau match',`<div class="form-grid">${['a','b'].map((side,i)=>`<label>${i?'Adversaire':'Équipe'}<select id="match${side.toUpperCase()}">${s.teams.map(t=>`<option value="${t.id}" ${t.id===(i?s.teams.find(x=>x.id!==(id||activeTeam))?.id:id||activeTeam)?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label>`).join('')}</div><p class="muted">Le score et les observations sont partagés entre les deux pages d’équipe.</p>`,()=>{const m=C.addMatch(s,$('matchA').value,$('matchB').value);activeMatch=m.id;activeTeam=m.a;view='observe';save();$('dialog').close();render()},'Lancer le match')}
function newSessionDialog(){if(!cls()){classDialog();return}openDialog('Nouvelle séance',`<p>La séance actuelle restera disponible dans le menu Séance.</p><label class="check"><input type="checkbox" id="reuseTeams" checked>Reprendre les équipes et les critères actuels</label><p class="muted">Les scores, observations et absences repartent à vide.</p>`,()=>{C.newSession(db,cls().id,$('reuseTeams').checked?session():null);activeTeam='';activeMatch='';selected.clear();view='home';save();$('dialog').close();render();settingsDialog()},'Créer la séance')}
function historyDialog(id){const p=pupil(id);openDialog('Parcours de '+p.name,db.sessions.filter(s=>s.classId===cls().id).map(s=>`<section class="criterion"><h3>${esc(s.label)} · ${esc(s.sport)}</h3><p class="muted">${esc(s.date)} · ${esc(s.teams.find(t=>t.members.includes(id))?.name||'Non affecté')}${s.absent.includes(id)?' · Absent':''}</p>${pupilSummary(p,s)}${[s,...s.matches].map(x=>x.notes?.[id]).filter(Boolean).map(n=>`<p class="muted">${esc(n)}</p>`).join('')}</section>`).join(''),null)}
function download(name,content,type){const u=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),60000)}
function buildReportHTML(){const s=session(),c=cls();return `<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Bilan · ${esc(c.name)}</title><style>
*{box-sizing:border-box}body{font:16px/1.5 system-ui,-apple-system,sans-serif;margin:0;background:#f3f6f0;color:#183d34}main{max-width:960px;margin:auto;padding:24px}header{margin-bottom:24px}h1{font-size:26px}h2{font-size:24px}h3{font-size:18px}.muted{color:#637269}a{color:inherit;text-decoration:none;display:inline-block;border:1px solid #d8e2d4;background:white;border-radius:12px;padding:12px 16px;min-height:48px}a:focus-visible{outline:3px solid #2873a5}.report-roster{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px}.report-profile{display:none}.report-profile:target{display:block}.report-profile:target~#report-list{display:none}.report-section{background:white;border:1px solid #d8e2d4;border-radius:16px;padding:20px;margin:16px 0}.report-criterion{padding:12px 0;border-top:1px solid #e4e9e1}.report-criterion p{margin:5px 0}.report-note{background:#f3f6f0;padding:12px;white-space:pre-wrap}.report-metrics{display:flex;flex-wrap:wrap;gap:12px}.report-metrics>div{flex:1;min-width:100px;padding:14px;background:#f0f5ec;border-radius:12px;text-align:center}.report-metrics strong{display:block;font-size:28px}.report-metrics span{font-size:13px}footer{font-size:12px;color:#637269;margin-top:24px}@media print{a,header p,#report-list{display:none}.report-profile:target{display:block}.report-section{break-inside:avoid}body{background:white}}
</style></head><body><main><header><h1>Bilan · ${esc(c.name)}</h1><p>${esc(s.label)} · ${esc(s.sport)} · ${esc(s.date)}</p></header>${c.students.map(p=>`<article id="${p.id}" class="report-profile"><a href="#report-list">← Liste des élèves</a>${pupilReport(p,s)}</article>`).join('')}<section id="report-list"><h2>Choisir un élève</h2><div class="report-roster">${c.students.map(p=>`<a href="#${p.id}">${esc(p.name)}</a>`).join('')}</div></section><footer>Bilan de la séance · Les niveaux indiquent le nombre de relevés à chaque niveau. Les compteurs sont cumulés. Les données collectives correspondent à l’équipe attribuée dans cette séance. Consultable hors connexion.</footer></main></body></html>`}
function exportReport(){download('SportCo-bilan-'+cls().name.replace(/[^a-z0-9_-]/gi,'_')+'-'+session().date+'.html',buildReportHTML(),'text/html;charset=utf-8')}
const actions={landing:()=>{$('dialog').close();view='landing';render()},'teacher-entry':()=>{view='home';render()},'student-gateway':()=>peerEntry(),'visual-guide':visualGuide,'student-session':b=>{const s=db.sessions.find(s=>s.id===b.dataset.id&&s.peerConfig);if(!s)return;db.selectedClass=s.classId;db.selectedSession=s.id;activeMatch='';activeTeam='';peerEntry()},'field-criteria':()=>{$('dialog').close();view='criteria';render()},'pupil-report':b=>{const p=pupil(b.dataset.id);if(p)openDialog('Bilan de l’élève',pupilReport(p,session()),null)},'clear-match-score':b=>{const m=session().matches.find(m=>m.id===b.dataset.id);if(!m)return;C.setScore(m,'a',null);C.setScore(m,'b',null);save();render();if($('dialog').open)updatePoolScores();notify('Score effacé : match non joué. Observations conservées.')},'pool-score':b=>{C.changeTeamScore(session(),b.dataset.match,b.dataset.team,Number(b.dataset.delta));save();render();updatePoolScores()},pool:()=>session().courts?poolDialog():poolSetup(),'pool-settings':poolSetup,'field-settings':fieldSettings,'court-step':b=>{const el=$('courtCount');el.value=Math.max(1,Math.min(100,(Number(el.value)||1)+Number(b.dataset.delta)))},'pool-observe':b=>observePoolMatch(b.dataset.id),'pool-next':nextPoolMatch,'terrain-back':()=>{terrainMode=false;view='home';if(document.fullscreenElement)document.exitFullscreen?.().catch(()=>{});render()},'quick-score':b=>{C.changeTeamScore(session(),b.dataset.match,b.dataset.team,Number(b.dataset.delta));save();render()},'quick-new-match':b=>{activeMatch=C.quickMatch(session(),activeTeam,b.dataset.opponent,true).id;save();render()},'terrain-mode':terrainToggle,'rename-team':b=>renameTeamDialog(b.dataset.id),'clock-start':b=>{const m=timerFor(b.dataset.id);C.clockStart(m);save();render()},'clock-pause':b=>{C.clockPause(timerFor(b.dataset.id));save();render()},'clock-reset':b=>{if(!confirm('Remettre ce chrono à sa durée initiale ?'))return;C.clockReset(timerFor(b.dataset.id));save();render()},'repair-roster':repairRosterDialog,'delete-class':deleteClassDialog,'roster-file':()=>$('rosterFile').click(),'clean-roster':()=>{$('studentNames').value=C.cleanRoster($('studentNames').value);notify('Liste nettoyée. Vérifie les noms avant d’enregistrer.')},transfer:transferDialog,view:b=>{view=b.dataset.view;render()},'class-dialog':classDialog,'new-session':newSessionDialog,settings:settingsDialog,presence:presenceDialog,'clear-selection':()=>{selected.clear();render()},'select-pupil':b=>{const id=b.dataset.id;if(selected.has(id))selected.delete(id);else{if(selected.size>=6){notify('Six élèves maximum par équipe.');return}selected.add(id)}render()},'create-team':()=>teamDialog(),'edit-team':b=>teamDialog(b.dataset.id),'open-team':b=>{activeTeam=b.dataset.id;activeMatch='';view='observe';render()},'switch-team':b=>{activeTeam=b.dataset.id;const m=session().matches.find(m=>m.id===activeMatch);if(!m||![m.a,m.b].includes(activeTeam))activeMatch=session().matches.slice().reverse().find(m=>[m.a,m.b].includes(activeTeam))?.id||'';render()},'criterion-dialog':()=>criterionDialog(),'edit-criterion':b=>criterionDialog(b.dataset.id),'match-dialog':b=>matchDialog(b.dataset.id),'observe-match':b=>{activeMatch=b.dataset.id;activeTeam=session().matches.find(m=>m.id===activeMatch).a;view='observe';render()},observation:b=>{C.setObservation(session(),activeMatch,b.dataset.subject,b.dataset.criterion,Number(b.dataset.value));save();render()},'clear-observation':b=>{C.setObservation(session(),activeMatch,b.dataset.subject,b.dataset.criterion,null);save();render()},counter:b=>{const current=context().observations?.[b.dataset.subject]?.[b.dataset.criterion];C.setObservation(session(),activeMatch,b.dataset.subject,b.dataset.criterion,Math.max(0,(current??0)+Number(b.dataset.delta)));save();render()},'close-dialog':()=>$('dialog').close(),'pupil-history':b=>historyDialog(b.dataset.id),export:()=>download('SportCo-sauvegarde-'+new Date().toLocaleDateString('sv-SE')+'.json',JSON.stringify(db,null,2),'application/json'),import:()=>$('importFile').click(),'export-report':exportReport,print:()=>window.print(),fullscreen:()=>{if(document.fullscreenElement)document.exitFullscreen?.();else document.documentElement.requestFullscreen?.().catch(()=>notify('Le plein écran n’est pas disponible dans ce navigateur.'))},help:()=>openDialog('Un carnet pour le terrain',`<ol class="help-list"><li><strong>Ajoute la classe</strong> : colle les noms, un élève par ligne.</li><li><strong>Crée les équipes</strong> : touche 3 à 6 élèves puis Créer cette équipe.</li><li><strong>Choisis les observations</strong> : un critère pour tous ou seulement certains élèves, et un mode de saisie.</li><li><strong>Sur le terrain</strong> : choisis une équipe puis une observation générale ou un match. Saisis les niveaux, compteurs et scores.</li><li><strong>Bilan</strong> : résultats, observations et parcours individuel. Une case vide signifie non observé ; zéro reste une observation.</li><li><strong>Après la séance</strong> : exporte une sauvegarde JSON. Elle permet de retrouver tes données sur un autre appareil.</li></ol><p class="muted">Ouvre l’application une première fois avec Internet pour préparer le fonctionnement hors ligne. Les données restent dans ce navigateur ; elles ne se synchronisent pas automatiquement entre appareils.</p>`,null),demo:()=>{if(db.classes.length)return;const {c,s}=C.addClass(db,'Classe démo',Array.from({length:12},(_,i)=>'Élève fictif '+(i+1)).join('\n'));C.putTeam(s,c,c.students.slice(0,4).map(p=>p.id),'Les Bleus',C.colors[0]);C.putTeam(s,c,c.students.slice(4,8).map(p=>p.id),'Les Oranges',C.colors[1]);C.putTeam(s,c,c.students.slice(8).map(p=>p.id),'Les Verts',C.colors[2]);save();render()}};
actions.help=visualGuide;
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b&&!b.disabled)run(()=>actions[b.dataset.action]?.(b))});
$('dialogForm').addEventListener('submit',e=>{e.preventDefault();run(()=>dialogSubmit?.())});
$('sportSelect').oninput=e=>{if(session()){session().sport=e.target.value.slice(0,100);save()}};$('sportSelect').onchange=e=>{if(session()){session().sport=e.target.value.trim()||'Activité à choisir';save();render()}};
$('classSelect').onchange=e=>{db.selectedClass=e.target.value;db.selectedSession='';selected.clear();activeTeam='';activeMatch='';normalize();save();render()};$('sessionSelect').onchange=e=>{db.selectedSession=e.target.value;selected.clear();activeTeam='';activeMatch='';save();render()};
document.addEventListener('input',e=>{if(e.target.id==='searchPupil'){const q=e.target.value.toLocaleLowerCase('fr');document.querySelectorAll('[data-search]').forEach(b=>b.hidden=!b.dataset.search.includes(q))}});
document.addEventListener('change',e=>run(()=>{const el=e.target;if(el.id==='quickOpponent'){if(el.value){activeMatch=C.quickMatch(session(),activeTeam,el.value).id;save()}else activeMatch='';render()}else if(el.dataset.duration){const m=timerFor(el.dataset.duration);const minutes=Number(el.value);if(!Number.isInteger(minutes)||minutes<1||minutes>120){el.value=Math.round((m.clock?.durationMs||300000)/60000);throw Error('Choisis une durée de 1 à 120 minutes.')}C.clockDuration(m,minutes*60);save();render()}else if(el.id==='contextSelect'){activeMatch=el.value;render()}else if(el.dataset.score){const m=session().matches.find(m=>m.id===el.dataset.match),raw=el.value;try{C.setScore(m,el.dataset.score,raw===''?null:Number(raw));save();render();if($('dialog').open&&$('poolRanking'))updatePoolScores()}catch(err){el.value=m[el.dataset.score==='a'?'scoreA':'scoreB']??'';throw err}}else if(el.dataset.note){context().notes[el.dataset.note]=el.value.slice(0,1000);save()}}));
$('importFile').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>10*1024*1024)throw Error('Fichier trop volumineux.');const next=C.validate(JSON.parse(await file.text()));openDialog('Importer la sauvegarde',`<p>${next.classes.length} classe(s) · ${next.sessions.length} séance(s).</p><p>Cette sauvegarde remplacera les données de ce navigateur. Exporte d’abord tes données actuelles si tu souhaites les garder.</p>`,()=>{db=next;selected.clear();activeTeam='';activeMatch='';view='home';save();$('dialog').close();render();notify('Sauvegarde importée.')},'Importer ces données')}catch(err){notify(err.message)}};
window.addEventListener('online',()=>notify('Connexion retrouvée. Tes données restent sur cet appareil.'));window.addEventListener('offline',()=>notify('Hors ligne : tu peux continuer les observations.'));
if('serviceWorker' in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').catch(()=>notify('Le mode hors ligne n’a pas pu être préparé.'));
render();


setInterval(()=>{let ended=false;for(const s of db.sessions)for(const m of [s,...s.matches]){if(m.clock?.running&&C.clockRemaining(m)===0){C.clockPause(m);ended=true;notify(m===s?'Temps écoulé · chrono de la séance':'Temps écoulé · '+(s.teams.find(t=>t.id===m.a)?.name||'')+' / '+(s.teams.find(t=>t.id===m.b)?.name||''))}const el=document.querySelector('[data-clock="'+m.id+'"]');if(el){const ms=C.clockRemaining(m);el.textContent=clockText(ms);el.classList.toggle('expired',ms===0);const status=document.querySelector('[data-clock-status="'+m.id+'"]');if(status)status.textContent=ms===0?'Temps écoulé':m.clock?.running?'En cours':'En pause / prêt';if(ms===0){const start=document.querySelector('[data-action="clock-pause"][data-id="'+m.id+'"]');if(start){start.disabled=true;start.textContent='Terminé'}const duration=document.querySelector('[data-duration="'+m.id+'"]');if(duration)duration.disabled=false}}}if(ended)save()},500);
